# --------------------------------------------------------------------
old_inject = r'(if\s*\(\s*textarea\s*\)\s*\{)(.*?)(logTest\(\s*\n?\s*\'Textarea injection\'\s*,.*?;\s*\n\s*\}\s*\n)'

def fix_injection(match):
    prefix = match.group(1)
    new_body = '''
  await textarea.click();
  // React-compatible value setter to enable send button
  await textarea.evaluate((el, value) => {
    const nativeSetter = Object.getOwnPropertyDescriptor(
      window.HTMLTextAreaElement.prototype, 'value'
    ).set;
    nativeSetter.call(el, value);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  }, 'runtime selector correlation test');
  await wait(1500);
  const currentVal = await page.evaluate(el => el.value, textarea);
'''
    logtest_part = match.group(3)
    return prefix + new_body + '  ' + logtest_part

content = re.sub(old_inject, fix_injection, content, flags=re.DOTALL)

# --------------------------------------------------------------------
# 2. Remove the old hardcoded send step (if present)
# --------------------------------------------------------------------
# Remove the entire block that was inserted earlier (between injection and completion endpoint)
old_send_block = r'''
  // ============================================
  // SEND TEST MESSAGE \(captures real endpoints\)
  // ============================================
  if \(textarea\) \{
    // Wait for the send button \(class _52c986b\) to be enabled
    try \{
      await page\.waitForSelector\('\._52c986b:not\(\[disabled\]\):not\(\[aria-disabled="true"\]\)', \{ timeout: 8000 \}\);
      const sendBtn = await page\.\$\(\._52c986b\'\);
