        console\.log\('📤 Test message sent, waiting for SSE stream\.\.\.'\);
        // Wait for SSE completions to appear
        await page\.waitForFunction\(\(\) => \(window\.__DS_COMPLETIONS__ \|\| \[\]\)\.length > 0, \{ timeout: 15000 \}\)\.catch\(\(\) => \{\}\);
        await wait\(3000\);
      \}
    \} catch \(e\) \{
      console\.log\('⚠️ Send button not available:', e\.message\);
    \}
  \}
'''

content = re.sub(old_send_block, '', content, flags=re.DOTALL)

# --------------------------------------------------------------------
# 3. Insert dynamic send step right before "COMPLETION ENDPOINT DETECTION"
# --------------------------------------------------------------------
dynamic_send = '''
  // ============================================
  // SEND TEST MESSAGE (uses discovered sendCandidates)
  // ============================================
  if (textarea && sendCandidates.length > 0) {
    // Find the best candidate: not disabled, likely the send button
    const enabledCandidates = sendCandidates.filter(c =>
      c.disabled !== 'true' && c.w > 0 && c.h > 0
    );
    // Heuristic: pick the one with 'send' or 'icon' in text/aria/cls, or the smallest non-zero area
    let target = enabledCandidates.find(c =>
      (c.text + ' ' + c.aria + ' ' + c.cls).toLowerCase().includes('send') ||
      (c.text + ' ' + c.aria + ' ' + c.cls).toLowerCase().includes('icon')
    );
    if (!target && enabledCandidates.length > 0) {
      // fallback: smallest visible button
      target = enabledCandidates.reduce((a, b) => (a.w * a.h < b.w * b.h ? a : b));
    }
    if (target) {
      try {
        const sendBtn = await page.evaluateHandle(
          (idx) => document.querySelectorAll('button,[role="button"],div[role="button"]')[idx],
          target.idx
        );
        if (sendBtn) {
          await sendBtn.click();
          console.log('📤 Test message sent using candidate', target.idx, 'Waiting for SSE...');
          await page.waitForFunction(() => (window.__DS_COMPLETIONS__ || []).length > 0, { timeout: 15000 }).catch(() => {});
