    }
  }

'''

# Insert before the COMPLETION ENDPOINT DETECTION comment
marker = r'(\s*// ============================================\s*// COMPLETION ENDPOINT DETECTION)'
content = re.sub(marker, dynamic_send + r'\1', content)

with open('tests/deepseek-full-suite.mjs', 'w') as f:
    f.write(content)

print("✅ Dynamic send step inserted. Hardcoded selector removed.")
PYEOF

